// Reactiva leads NO_ANSWER cuyo nextFollowUpAt ya pasó -> los vuelve a poner
// disponibles para que el GET Queue (status=NOT_CONTACTED) los recoja.
// FIX: el filtro ?status=NO_ANSWER de la API no es confiable (mismo bug que
// el filtro de country), así que acá se valida el status real del lead
// antes de reactivar — nunca reactivar algo que no está en NO_ANSWER.
const now = new Date();
const leads = ($input.first().json.leads) || [];
const due = leads.filter(l =>
  l.status === 'NO_ANSWER' &&
  l.nextFollowUpAt &&
  new Date(l.nextFollowUpAt) <= now
);
const skipped = leads.filter(l => l.nextFollowUpAt && new Date(l.nextFollowUpAt) <= now && l.status !== 'NO_ANSWER');
if (skipped.length) {
  console.log('⚠️ Omitidos (status ya no es NO_ANSWER):', skipped.map(l => `${l.id}:${l.status}`).join(', '));
}
console.log('⏰', due.length, 'leads NO_ANSWER vencidos para reactivar (de', leads.length, 'total recibidos)');
return due.map(l => ({ json: { lead_id: l.id } }));

