// Lee wf2_provider_config (MySQL). Fail-open: si falta tabla/fila,
// ese proveedor queda HABILITADO por defecto.
const rows = $input.all().map(i => i.json).filter(r => r && r.provider);

function isEnabled(providerName) {
  const row = rows.find(r => String(r.provider).toLowerCase() === providerName);
  if (!row) return true;
  return Number(row.enabled) === 1;
}

const asterisk_enabled = isEnabled('asterisk');
const stringee_enabled = isEnabled('stringee');
console.log('🔀 Providers activos —', 'Asterisk:', asterisk_enabled, '| Stringee:', stringee_enabled);
return [{ json: { asterisk_enabled, stringee_enabled } }];

const resp = $('🔐 Login LeadStudio').item.json;
console.error('❌ WF2: Login a LeadStudio falló', JSON.stringify(resp));
return [{ json: { error: true, message: 'LeadStudio auth failed', response: resp } }];

// Normaliza leads de LeadStudio. Filtro primario: dialCode en el GET Queue.
// Filtro secundario (defensa): detecta país por el TELÉFONO, por si algún
// lead viene mal clasificado o el filtro de la API falla.
const EXPECTED = 'india';

const PREFIX_MAP = [
  { prefix: '977', country: 'nepal' },   // el más largo primero
  { prefix: '91',  country: 'india' }
];
const CODE_MAP = { NP: 'nepal', IN: 'india', NEPAL: 'nepal', INDIA: 'india' };

function detectCountry(l) {
  const raw = String(l.phone || '').trim();
  const digits = raw.replace(/[^0-9]/g, '');
  if (raw.startsWith('+') || digits.length >= 11) {
    const hit = PREFIX_MAP.find(m => digits.startsWith(m.prefix));
    if (hit) return hit.country;
  }
  const code = String(l.countryCode || l.country || '').trim().toUpperCase();
  return CODE_MAP[code] || null;
}

const leads = ($input.first().json.leads) || [];
const out = [];
const rejected = [];

for (const l of leads) {
  const detected = detectCountry(l);
  if (detected !== EXPECTED) {
    rejected.push({ id: l.id, phone: l.phone, detected });
    continue;
  }
  out.push({ json: {
    lead_id: l.id,
    full_name: l.name,
    phone: l.phone,
    country: detected,
    language: String(l.language || 'hi').trim().toLowerCase(),
    status: String(l.status || '').trim().toUpperCase(),
    call_attempts: Number(l.attempts || 0),
    doNotCall: !!l.doNotCall,
    _source_country: EXPECTED
  }});
}

console.log(`🏷️ Normalizar ${EXPECTED}: ${out.length} OK | ${rejected.length} descartados (otro país)`,
  JSON.stringify(rejected).slice(0, 400));
return out;

// Normaliza leads de LeadStudio. Filtro primario: dialCode en el GET Queue.
// Filtro secundario (defensa): detecta país por el TELÉFONO, por si algún
// lead viene mal clasificado o el filtro de la API falla.
const EXPECTED = 'nepal';

const PREFIX_MAP = [
  { prefix: '977', country: 'nepal' },   // el más largo primero
  { prefix: '91',  country: 'india' }
];
const CODE_MAP = { NP: 'nepal', IN: 'india', NEPAL: 'nepal', INDIA: 'india' };

function detectCountry(l) {
  const raw = String(l.phone || '').trim();
  const digits = raw.replace(/[^0-9]/g, '');
  if (raw.startsWith('+') || digits.length >= 11) {
    const hit = PREFIX_MAP.find(m => digits.startsWith(m.prefix));
    if (hit) return hit.country;
  }
  const code = String(l.countryCode || l.country || '').trim().toUpperCase();
  return CODE_MAP[code] || null;
}

const leads = ($input.first().json.leads) || [];
const out = [];
const rejected = [];

for (const l of leads) {
  const detected = detectCountry(l);
  if (detected !== EXPECTED) {
    rejected.push({ id: l.id, phone: l.phone, detected });
    continue;
  }
  out.push({ json: {
    lead_id: l.id,
    full_name: l.name,
    phone: l.phone,
    country: detected,
    language: String(l.language || 'hi').trim().toLowerCase(),
    status: String(l.status || '').trim().toUpperCase(),
    call_attempts: Number(l.attempts || 0),
    doNotCall: !!l.doNotCall,
    _source_country: EXPECTED
  }});
}

console.log(`🏷️ Normalizar ${EXPECTED}: ${out.length} OK | ${rejected.length} descartados (otro país)`,
  JSON.stringify(rejected).slice(0, 400));
return out;

// MULTI-PAIS — India + Nepal (API LeadStudio). Batch SEPARADO por país + dedup.
// CRITERIO DE LISTO PARA LLAMAR: status === 'NOT_CONTACTED'.
const COUNTRY_CFG = {
  india: { dialPrefix: '+91', language: 'hi', batchSize: 10,
    agent_id: 'agent_5701kramx550e3qs2tm11661b48p',
    agent_phone_number_id: 'phnum_7801kyktmabxembteqce884tanb6' },
  nepal: { dialPrefix: '+977', language: 'hi', batchSize: 10,
    agent_id: 'agent_7601m209ntj3fyrbg0dcq6w507yq',
    agent_phone_number_id: 'phnum_7801kyktmabxembteqce884tanb6' }
};

function normalizePhone(rawPhone, countryKey) {
  let p = String(rawPhone || '').replace(/[^0-9+]/g, '');
  if (!p) return '';
  const cfg = COUNTRY_CFG[countryKey];
  if (p.startsWith('+')) return p;
  const prefixDigits = cfg.dialPrefix.replace('+', '');
  if (p.startsWith(prefixDigits) && p.length > prefixDigits.length + 6) return '+' + p;
  return cfg.dialPrefix + p;
}

const buckets = Object.fromEntries(Object.keys(COUNTRY_CFG).map(k => [k, []]));
const seen = new Set();
const skipped = [];

for (const item of $input.all()) {
  const r = { ...(item.json || {}) };
  if (!r.lead_id) continue;
  if (seen.has(r.lead_id)) { skipped.push({ lead_id: r.lead_id, reason: 'duplicado' }); continue; }
  seen.add(r.lead_id);

  if (r.doNotCall) { skipped.push({ lead_id: r.lead_id, reason: 'doNotCall' }); continue; }
  if (r.status !== 'NOT_CONTACTED') { skipped.push({ lead_id: r.lead_id, reason: `status=${r.status}` }); continue; }

  const cfg = COUNTRY_CFG[r.country];
  if (!cfg) { skipped.push({ lead_id: r.lead_id, reason: `country no soportado: ${r.country}` }); continue; }

  const phone = normalizePhone(r.phone, r.country);
  if (!/^\+[1-9]\d{7,14}$/.test(phone)) { skipped.push({ lead_id: r.lead_id, reason: `bad phone: '${r.phone}'` }); continue; }

  if (!phone.startsWith(cfg.dialPrefix)) {
    skipped.push({ lead_id: r.lead_id, reason: `prefijo ${phone.slice(0,4)} no es de ${r.country}` });
    continue;
  }

  buckets[r.country].push({ json: {
    ...r, phone,
    _agent_id: cfg.agent_id,
    _agent_phone_number_id: cfg.agent_phone_number_id,
    language: r.language || cfg.language
  }});
}

const out = [];
for (const [country, list] of Object.entries(buckets)) {
  const take = list.slice(0, COUNTRY_CFG[country].batchSize);
  console.log(`⚙️ Asterisk ${country}: ${list.length} elegibles → ${take.length} al batch`);
  out.push(...take);
}
console.log('⏭️ skipped:', skipped.length, JSON.stringify(skipped).slice(0, 500));
return out;

