const items = $input.all();
const leads = $('⚙️ Select Batch + Country Route (Asterisk)1').all();
const now = new Date().toISOString();
const nowDate = new Date();

const NO_ANSWER_CODES = ['603', '408', '486'];

function addHours(date, h) {
  return new Date(date.getTime() + h * 60 * 60 * 1000).toISOString();
}

function addBusinessDays(date, days) {
  const result = new Date(date.getTime());
  let added = 0;
  while (added < days) {
    result.setDate(result.getDate() + 1);
    const dow = result.getDay();
    if (dow !== 0 && dow !== 6) added++;
  }
  return result.toISOString();
}

return items.map((item, i) => {
  const resp = item.json || {};
  const lead = (leads[i] || leads[0]).json;
  const body = resp.body ?? resp;
  const conversationId = body.conversation_id || '';
  const success = body.success === true;
  const message = String(body.message || '');

  const sipMatch = message.match(/SIP\s*(\d{3})/i) || message.match(/\b(\d{3})\b/);
  const sipCode = sipMatch ? sipMatch[1] : null;
  const isNoAnswer = sipCode && NO_ANSWER_CODES.includes(sipCode);

  const attempts = Number(lead.call_attempts || 0) + 1;

  let status, last_call_status, notes, nextFollowUpAt = null;

  if (success && conversationId) {
    status = 'CONTACTED';
    last_call_status = 'ANSWERED';
    notes = '🟢 Call connected: ' + conversationId;
  } else if (isNoAnswer) {
    last_call_status = 'NO_ANSWER_SIP_' + sipCode;

    const posInCycle = ((attempts - 1) % 3) + 1;
    const cycle = Math.ceil(attempts / 3);

    if (posInCycle === 1) {
      status = 'NO_ANSWER';
      nextFollowUpAt = addHours(nowDate, 2);
      notes = `🟡 No answer (SIP ${sipCode}) — attempt ${attempts} (cycle ${cycle}, pos 1/3) — next in 2h`;
    } else if (posInCycle === 2) {
      status = 'NO_ANSWER';
      nextFollowUpAt = addHours(nowDate, 3);
      notes = `🟡 No answer (SIP ${sipCode}) — attempt ${attempts} (cycle ${cycle}, pos 2/3) — next in 3h`;
    } else {
      if (cycle === 1) {
        status = 'NO_ANSWER';
        nextFollowUpAt = addBusinessDays(nowDate, 2);
        notes = `🟡 No answer (SIP ${sipCode}) — end of cycle 1 (3/3) — next cycle in 2 business days`;
      } else if (cycle === 2) {
        status = 'NO_ANSWER';
        nextFollowUpAt = addBusinessDays(nowDate, 3);
        notes = `🟡 No answer (SIP ${sipCode}) — end of cycle 2 (3/3) — next cycle in 3 business days`;
      } else {
        status = 'CLOSED';
        nextFollowUpAt = null;
        notes = `⛔ No answer (SIP ${sipCode}) — end of cycle 3 (9 total attempts) — CLOSED`;
      }
    }
  } else {
    status = 'UNREACHABLE';
    last_call_status = sipCode ? ('SIP_' + sipCode) : 'OTHER_ERROR';
    notes = '🔴 Unreachable: ' + message.slice(0, 150);
  }

  console.log('📞 Asterisk —', lead.lead_id, '| attempt:', attempts, '| status:', status, '| next:', nextFollowUpAt);

  return { json: {
    lead_id: lead.lead_id,
    country: lead.country,
    elevenlabs_call_id: conversationId,
    status,
    last_call_status,
    notes,
    call_attempts: attempts,
    last_call_time: now,
    nextFollowUpAt
  }};
});

// Normaliza + selecciona batch de leads India (API LeadStudio) para Stringee.
// CRITERIO DE LISTO PARA LLAMAR: status === 'NOT_CONTACTED'. BATCH_SIZE=1 (capacidad real del canal).
function toE164(raw) {
  if (raw === undefined || raw === null) return '';
  let p = String(raw).replace(/[^0-9+]/g, '');
  if (!p) return '';
  if (p.startsWith('+')) return p;
  if (p.length >= 8 && p.length <= 15) return '+' + p;
  return '';
}

const BATCH_SIZE = 1;
const leads = ($input.first().json.leads) || [];
const attempts = [];
const skipped = [];

for (const l of leads) {
  const status = String(l.status || '').trim().toUpperCase();
  if (!l.id) { skipped.push({ lead_id: 'EMPTY', reason: 'missing id' }); continue; }
  if (l.doNotCall) { skipped.push({ lead_id: l.id, reason: 'doNotCall' }); continue; }
  if (status !== 'NOT_CONTACTED') { skipped.push({ lead_id: l.id, reason: `status=${status} (no es NOT_CONTACTED)` }); continue; }

  const phone = toE164(l.phone);
  if (!phone) { skipped.push({ lead_id: l.id, reason: `bad phone: '${l.phone}'` }); continue; }

  attempts.push({ json: {
    lead_id: String(l.id), full_name: String(l.name || '').trim() || 'User',
    phone, country: l.country || 'India',
    language: String(l.language || 'hi').trim().toLowerCase(),
    call_attempts: Number(l.attempts || 0)
  }});
}

console.log('⚙️ Stringee — elegibles (NOT_CONTACTED):', attempts.length, '| skipped:', skipped.length, JSON.stringify(skipped).slice(0,500));
return attempts.slice(0, BATCH_SIZE);

// Stringee: el worker solo confirma que la llamada se DISPARÓ (job_id), no si
// contestó o no — eso llega después por webhook a otro workflow. Por eso acá
// solo se puede marcar ACTIVE (se disparó bien) o UNREACHABLE (falló el disparo).
// El ciclo de reintentos NO_ANSWER (2h/3h/2d/3d) para Stringee no se puede calcular
// en este punto — falta esa pieza en el workflow que reciba el resultado final.
const items = $input.all();
const leads = $('⚙️ Normalize & Select (Stringee)1').all();
const now = new Date().toISOString();

return items.map((item, i) => {
  const resp = item.json || {};
  const lead = (leads[i] || leads[0]).json;
  const statusCode = Number(resp.statusCode ?? resp.status ?? (resp.headers ? 200 : 0));
  const body = resp.body ?? resp;
  const jobId = String(body.job_id || body.jobId || '');

  let status, last_call_status, notes;
  if (statusCode >= 200 && statusCode < 300 && body.ok === true && jobId) {
    status = 'ATTEMPTING';
    last_call_status = 'DISPATCHED';
    notes = '🟢 Stringee worker job: ' + jobId;
  } else if (statusCode >= 400) {
    status = 'UNREACHABLE';
    last_call_status = 'HTTP_' + statusCode;
    notes = '🔴 Stringee Worker ' + statusCode + ': ' + JSON.stringify(body).slice(0, 200);
  } else {
    status = 'UNREACHABLE';
    last_call_status = 'NO_JOB_ID';
    notes = '🟡 Unexpected Stringee worker response: ' + JSON.stringify(body).slice(0, 200);
  }

  console.log('📞 Stringee —', lead.lead_id, '| HTTP', statusCode, '| status:', status, '| job_id:', jobId);

  return { json: {
    lead_id: lead.lead_id,
    status,
    last_call_status,
    notes,
    call_attempts: Number(lead.call_attempts || 0) + 1,
    last_call_time: now,
    nextFollowUpAt: null
  }};
});

// Lee wf2_provider_config. Fail-open: si falta la tabla/fila, el proveedor queda HABILITADO.
const rows = $input.all().map(i => i.json).filter(r => r && r.provider);
function isEnabled(name) {
  const row = rows.find(r => String(r.provider).toLowerCase() === name);
  if (!row) return true;
  return Number(row.enabled) === 1;
}
const asterisk_enabled = isEnabled('asterisk');
const stringee_enabled = isEnabled('stringee');
console.log('🔀 Providers —', 'Asterisk:', asterisk_enabled, '| Stringee:', stringee_enabled);
return [{ json: { asterisk_enabled, stringee_enabled } }];

const resp = $('🔐 Login LeadStudio1').first().json;
console.error('❌ WF2: Login a LeadStudio falló', JSON.stringify(resp).slice(0, 500));
return [{ json: { error: true, message: 'LeadStudio auth failed', response: resp } }];

const BASE = 'https://lead-studio-9gnl.onrender.com/api';
const TOKEN = $('🔐 Login LeadStudio1').first().json.accessToken;
const self = this;

async function api(method, path, opts = {}) {
  try {
    const r = await self.helpers.httpRequest({
      method,
      url: BASE + path,
      qs: opts.qs,
      body: opts.body,
      json: true,
      headers: {
        Authorization: 'Bearer ' + TOKEN,
        'Content-Type': 'application/json'
      },
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
      timeout: 20000
    });

    return {
      ok: r.statusCode >= 200 && r.statusCode < 300,
      status: r.statusCode,
      body: r.body || {}
    };
  } catch (e) {
    return {
      ok: false,
      status: 0,
      body: { error: String(e.message || e) }
    };
  }
}

// ============================================================================
// 📥 FETCH + LOCK (ASTERISK)
//
// Regla:
// 3 ciclos x 3 intentos = máximo 9.
//
// attempts 0-8  -> puede despacharse.
// attempts >= 9 -> NO se despacha.
//                  status CLOSED.
//                  stage LOST.
//
// El bloqueo ocurre ANTES de ElevenLabs.
// ============================================================================

const MAX_ATTEMPTS = 9;

const COUNTRIES = [
  {
    key: 'india',
    dialCode: '91',
    prefix: '+91',
    batchSize: 10,
    minDigits: 10,
    maxDigits: 10,
    language: 'hi',
    agent_id: 'agent_5701kramx550e3qs2tm11661b48p',
    agent_phone_number_id: 'phnum_7801kyktmabxembteqce884tanb6'
  },
  {
    key: 'nepal',
    dialCode: '977',
    prefix: '+977',
    batchSize: 6,
    minDigits: 8,
    maxDigits: 10,
    language: 'hi',
    agent_id: 'agent_7601m209ntj3fyrbg0dcq6w507yq',
    agent_phone_number_id: 'phnum_7801kyktmabxembteqce884tanb6'
  }
];

const FETCH_MULT = 3;

function normalizePhone(raw, prefix) {
  let p = String(raw || '').replace(/[^0-9+]/g, '');

  if (!p) return '';

  if (p.startsWith('+')) return p;

  const digits = prefix.replace('+', '');

  if (
    p.startsWith(digits) &&
    p.length > digits.length + 6
  ) {
    return '+' + p;
  }

  return prefix + p;
}

function safeAttempts(value) {
  const n = Number(value);

  if (!Number.isFinite(n) || n < 0) {
    return 0;
  }

  return Math.trunc(n);
}

// Cierra un lead agotado.
// Primero CLOSED para impedir nuevas llamadas.
// Después intenta mover el stage a LOST.
async function closeExhaustedLead(leadId, attempts, country) {
  const close = await api(
    'PATCH',
    `/leads/${leadId}`,
    {
      body: {
        status: 'CLOSED'
      }
    }
  );

  if (!close.ok) {
    console.error(
      `🚨 Asterisk ${country}: no se pudo cerrar ${leadId} ` +
      `con ${attempts} intentos. HTTP ${close.status}. ` +
      `Por seguridad NO se despacha.`
    );

    return {
      closed: false,
      lost: false
    };
  }

  const lost = await api(
    'PATCH',
    `/leads/${leadId}`,
    {
      body: {
        stage: 'LOST'
      }
    }
  );

  if (!lost.ok) {
    console.error(
      `⚠️ Asterisk ${country}: ${leadId} quedó CLOSED, ` +
      `pero stage LOST falló HTTP ${lost.status}.`
    );
  }

  console.log(
    `⛔ Asterisk ${country}: ${leadId} reached ` +
    `${attempts}/${MAX_ATTEMPTS} attempts → no dispatch`
  );

  return {
    closed: true,
    lost: lost.ok
  };
}

const out = [];

for (const c of COUNTRIES) {
  const limit = Math.min(
    200,
    c.batchSize * FETCH_MULT
  );

  let offset = 0;

  if (c.fromEnd) {
    const t = await api(
      'GET',
      '/leads',
      {
        qs: {
          status: 'NOT_CONTACTED',
          dialCode: c.dialCode,
          limit: 1,
          offset: 0
        }
      }
    );

    offset = t.ok
      ? Math.max(
          0,
          Number(t.body.total || 0) - limit
        )
      : 0;
  }

  const r = await api(
    'GET',
    '/leads',
    {
      qs: {
        status: 'NOT_CONTACTED',
        dialCode: c.dialCode,
        limit,
        offset
      }
    }
  );

  if (!r.ok) {
    console.error(
      `❌ Asterisk ${c.key}: GET /leads falló HTTP ${r.status}`,
      JSON.stringify(r.body).slice(0, 300)
    );

    continue;
  }

  const leads = r.body.leads || [];
  const totalDisponibles = Number(r.body.total || 0);

  let taken = 0;
  let invalid = 0;
  let lockFail = 0;
  let exhausted = 0;

  for (const l of leads) {
    if (taken >= c.batchSize) break;

    if (!l || !l.id) continue;

    if (
      String(l.status || '').toUpperCase() !== 'NOT_CONTACTED'
    ) {
      continue;
    }

    const currentAttempts = safeAttempts(l.attempts);

    // ==========================================================
    // HARD LIMIT
    // Si ya tiene 9 intentos o más, nunca llega a ElevenLabs.
    // ==========================================================
    if (currentAttempts >= MAX_ATTEMPTS) {
      await closeExhaustedLead(
        l.id,
        currentAttempts,
        c.key
      );

      exhausted++;
      continue;
    }

    if (l.doNotCall) {
      await api(
        'PATCH',
        `/leads/${l.id}`,
        {
          body: {
            status: 'CLOSED'
          }
        }
      );

      invalid++;
      continue;
    }

    const phone = normalizePhone(
      l.phone,
      c.prefix
    );

    const national = phone.slice(
      c.prefix.length
    );

    const validPhone =
      /^\+[1-9]\d{7,14}$/.test(phone) &&
      phone.startsWith(c.prefix) &&
      national.length >= c.minDigits &&
      national.length <= c.maxDigits;

    if (!validPhone) {
      await api(
        'PATCH',
        `/leads/${l.id}`,
        {
          body: {
            status: 'UNREACHABLE'
          }
        }
      );

      console.log(
        `🚫 ${c.key}: teléfono inválido '${l.phone}' ` +
        `→ UNREACHABLE (${l.id})`
      );

      invalid++;
      continue;
    }

    // Lock antes de llamar.
    const lock = await api(
      'PATCH',
      `/leads/${l.id}`,
      {
        body: {
          status: 'ATTEMPTING'
        }
      }
    );

    if (!lock.ok) {
      lockFail++;

      console.error(
        `🔒❌ ${c.key}: no se pudo bloquear ${l.id} ` +
        `HTTP ${lock.status}`
      );

      continue;
    }

    out.push({
      json: {
        provider: 'asterisk',
        lead_id: l.id,
        full_name:
          String(l.name || '').trim() || 'User',
        phone,
        country: c.key,
        language:
          String(l.language || c.language)
            .trim()
            .toLowerCase(),

        call_attempts: currentAttempts,

        _agent_id: c.agent_id,
        _agent_phone_number_id:
          c.agent_phone_number_id,

        _from_number: c.lines
          ? c.lines[taken % c.lines.length]
          : (c.from_number || '')
      }
    });

    taken++;
  }

  const msg =
    `📥 Asterisk ${c.key}: ` +
    `${totalDisponibles} NOT_CONTACTED | ` +
    `${leads.length} leídos | ` +
    `${taken} bloqueados | ` +
    `${exhausted} agotaron ${MAX_ATTEMPTS} intentos | ` +
    `${invalid} inválidos | ` +
    `${lockFail} lock fallidos`;

  if (
    taken === 0 &&
    totalDisponibles > 0
  ) {
    console.error(
      '🚨 Hay leads disponibles pero 0 llegaron al batch — ' +
      msg
    );
  } else {
    console.log(msg);
  }
}

return out;

// ============================================================================
// 🔍 CLASSIFY DIAL RESULT (ASTERISK)
//
// CRM visible text: ENGLISH ONLY.
// Comentarios/logs internos: español.
//
// Ciclo 1: attempts 1-3
// Ciclo 2: attempts 4-6
// Ciclo 3: attempts 7-9
//
// Attempt 9 + NO_ANSWER -> CLOSED + LOST.
// ============================================================================

const items = $input.all();
const src = $('📥 Fetch + Lock (Asterisk)').all();

const nowDate = new Date();

const NO_ANSWER_CODES = [
  '603',
  '408',
  '486'
];

const MAX_ATTEMPTS = 9;
const ATTEMPTS_PER_CYCLE = 3;
const MAX_CYCLES = 3;

function addHours(d, h) {
  return new Date(
    d.getTime() + h * 3600000
  ).toISOString();
}

function addBusinessDays(d, days) {
  const r = new Date(d.getTime());
  let added = 0;

  while (added < days) {
    r.setDate(r.getDate() + 1);

    const weekday = r.getDay();

    if (
      weekday !== 0 &&
      weekday !== 6
    ) {
      added++;
    }
  }

  return r.toISOString();
}

function safeAttempts(value) {
  const n = Number(value);

  if (!Number.isFinite(n) || n < 0) {
    return 0;
  }

  return Math.trunc(n);
}

function pickLead(item, i) {
  let idx = i;

  const p = item.pairedItem;

  if (
    p !== undefined &&
    p !== null
  ) {
    const pi = Array.isArray(p)
      ? p[0]
      : p;

    if (typeof pi === 'number') {
      idx = pi;
    } else if (
      pi &&
      typeof pi.item === 'number'
    ) {
      idx = pi.item;
    }
  }

  return (
    src[idx] ||
    src[i] ||
    src[0]
  ).json;
}

function isProviderFail(httpStatus, message) {
  if (
    httpStatus === 0 ||
    httpStatus === 401 ||
    httpStatus === 402 ||
    httpStatus === 403 ||
    httpStatus === 429 ||
    httpStatus >= 500
  ) {
    return true;
  }

  return /concurren|rate.?limit|quota|credit|insufficient|too many/i.test(
    message
  );
}

let providerFails = 0;

const out = items.map((item, i) => {
  const lead = pickLead(item, i);

  const resp = item.json || {};

  const httpStatus = Number(
    resp.statusCode ?? 0
  );

  const body =
    (
      resp.body !== undefined
        ? resp.body
        : resp
    ) || {};

  const detail = body.detail;

  let message =
    body.message ||
    (
      detail &&
      (
        typeof detail === 'string'
          ? detail
          : (
              detail.message ||
              JSON.stringify(detail)
            )
      )
    ) ||
    body.error ||
    resp.error ||
    '';

  if (typeof message !== 'string') {
    message = JSON.stringify(message);
  }

  const conversationId =
    body.conversation_id || '';

  const success =
    body.success === true;

  const sipMatch =
    message.match(/SIP\s*(\d{3})/i) ||
    message.match(/\b(\d{3})\b/);

  const sipCode = sipMatch
    ? sipMatch[1]
    : null;

  const isNoAnswer =
    !!sipCode &&
    NO_ANSWER_CODES.includes(sipCode);

  const previousAttempts =
    safeAttempts(lead.call_attempts);

  const attempts =
    previousAttempts + 1;

  let r;

  // ==========================================================
  // ANSWERED
  // Aunque sea attempt 9, si contestó NO va a LOST.
  // ==========================================================
  if (
    success &&
    conversationId
  ) {
    r = {
      status: 'CONTACTED',
      stage: null,
      attempts,
      nextFollowUpAt: null,
      last_call_status: 'ANSWERED',
      outcome: 'CONNECTED',
      callStatus: 'ANSWERED',
      notes:
        'Call connected successfully: ' +
        conversationId,
      logFollowup: true
    };
  }

  // ==========================================================
  // NO ANSWER
  // ==========================================================
  else if (isNoAnswer) {
    const pos =
      ((attempts - 1) % ATTEMPTS_PER_CYCLE) + 1;

    const cycle =
      Math.ceil(
        attempts / ATTEMPTS_PER_CYCLE
      );

    let status = 'NO_ANSWER';
    let stage = null;
    let next = null;
    let notes = '';

    // Intento 9 = fin definitivo.
    if (attempts >= MAX_ATTEMPTS) {
      status = 'CLOSED';
      stage = 'LOST';
      next = null;

      notes =
        `No answer (SIP ${sipCode}) — ` +
        `end of cycle ${MAX_CYCLES} (3/3) — ` +
        `maximum ${MAX_ATTEMPTS} call attempts reached.`;
    }

    else if (pos === 1) {
      next = addHours(
        nowDate,
        2
      );

      notes =
        `No answer (SIP ${sipCode}) — ` +
        `attempt ${attempts} ` +
        `(cycle ${cycle}, 1/3) — ` +
        `next attempt in 2 hours.`;
    }

    else if (pos === 2) {
      next = addHours(
        nowDate,
        3
      );

      notes =
        `No answer (SIP ${sipCode}) — ` +
        `attempt ${attempts} ` +
        `(cycle ${cycle}, 2/3) — ` +
        `next attempt in 3 hours.`;
    }

    else if (cycle === 1) {
      next = addBusinessDays(
        nowDate,
        2
      );

      notes =
        `No answer (SIP ${sipCode}) — ` +
        `end of cycle 1 (3/3) — ` +
        `next cycle in 2 business days.`;
    }

    else if (cycle === 2) {
      next = addBusinessDays(
        nowDate,
        3
      );

      notes =
        `No answer (SIP ${sipCode}) — ` +
        `end of cycle 2 (3/3) — ` +
        `next cycle in 3 business days.`;
    }

    else {
      // Defensa extra. No debería alcanzarse.
      status = 'CLOSED';
      stage = 'LOST';
      next = null;

      notes =
        `No answer (SIP ${sipCode}) — ` +
        `maximum ${MAX_ATTEMPTS} call attempts reached.`;
    }

    r = {
      status,
      stage,
      attempts,
      nextFollowUpAt: next,
      last_call_status:
        'NO_ANSWER_SIP_' + sipCode,
      outcome: 'NO_ANSWER',
      callStatus: 'NO_ANSWER',
      notes,
      logFollowup: true
    };
  }

  // ==========================================================
  // ERROR DEL PROVEEDOR
  // No consume intento.
  // ==========================================================
  else if (
    isProviderFail(
      httpStatus,
      message
    )
  ) {
    providerFails++;

    r = {
      status: 'NOT_CONTACTED',
      stage: null,
      attempts: null,
      nextFollowUpAt: null,
      last_call_status:
        'PROVIDER_ERROR_' + httpStatus,
      outcome: null,
      callStatus: null,
      notes:
        'Provider error. The lead was returned to the call queue.',
      logFollowup: false
    };
  }

  // ==========================================================
  // OTRO ERROR
  // ==========================================================
  else {
    const exhausted =
      attempts >= MAX_ATTEMPTS;

    r = {
      status: exhausted
        ? 'CLOSED'
        : 'UNREACHABLE',

      stage: exhausted
        ? 'LOST'
        : null,

      attempts,
      nextFollowUpAt: null,

      last_call_status:
        sipCode
          ? 'SIP_' + sipCode
          : 'OTHER_ERROR',

      outcome: 'WRONG_NUMBER',
      callStatus: 'FAILED',

      notes: exhausted
        ? (
            `Call failed — attempt ${attempts}/${MAX_ATTEMPTS} — ` +
            `maximum call attempts reached.`
          )
        : (
            `Call failed or unreachable: ` +
            message.slice(0, 150)
          ),

      logFollowup: true
    };
  }

  console.log(
    '📞 Asterisk —',
    lead.lead_id,
    '| HTTP',
    httpStatus,
    '| attempt',
    attempts,
    '| →',
    r.status,
    r.stage
      ? '| stage ' + r.stage
      : '',
    '| next:',
    r.nextFollowUpAt
  );

  return {
    json: {
      provider: 'asterisk',
      lead_id: lead.lead_id,
      country: lead.country,
      elevenlabs_call_id:
        conversationId,
      last_call_time:
        nowDate.toISOString(),
      ...r
    }
  };
});

if (providerFails > 0) {
  console.error(
    `🚨 ElevenLabs: ${providerFails}/${items.length} ` +
    `llamadas fallaron por problema del proveedor.`
  );
}

return out;

const BASE = 'https://lead-studio-9gnl.onrender.com/api';
const TOKEN = $('🔐 Login LeadStudio1').first().json.accessToken;
const self = this;

async function api(method, path, opts = {}) {
  try {
    const r = await self.helpers.httpRequest({
      method,
      url: BASE + path,
      qs: opts.qs,
      body: opts.body,
      json: true,
      headers: {
        Authorization: 'Bearer ' + TOKEN,
        'Content-Type': 'application/json'
      },
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
      timeout: 20000
    });

    return {
      ok:
        r.statusCode >= 200 &&
        r.statusCode < 300,
      status: r.statusCode,
      body: r.body || {}
    };
  } catch (e) {
    return {
      ok: false,
      status: 0,
      body: {
        error: String(
          e.message || e
        )
      }
    };
  }
}

// ============================================================================
// 🏁 GUARDAR RESULTADO (ASTERISK)
//
// 1. POST followup.
//    LeadStudio incrementa attempts.
//
// 2. PATCH status.
//
// 3. Si Classify pidió LOST,
//    PATCH stage por separado.
//
// Se separa status de stage para no poner en riesgo
// el cierre del lead si el stage fuera rechazado.
// ============================================================================

const out = [];
let fails = 0;
let deferred = 0;

// Este nodo va DESPUÉS del registro diferido (MySQL): $input trae las claves confirmadas;
// las llamadas clasificadas vienen del nodo Classify.
const confirmedKeys = new Set(
  $input.all().map(i => (i.json || {}).event_key).filter(Boolean).map(String)
);

for (const item of $('🔍 Classify Dial Result (Asterisk)').all()) {
  const j = item.json || {};

  if (!j.lead_id) {
    console.error(
      '❌ Asterisk: item sin lead_id'
    );
    continue;
  }

  // ------------------------------------------------------------
  // DIFERIDA (llamada contestada)
  // LeadStudio fija durationSeconds en el POST y no lo deja editar
  // después. Esta llamada acaba de ser contestada: todavía no existe
  // el billsec. WF9 crea la ÚNICA Activity al terminar la llamada
  // (durationSeconds = CDR.billsec) y aplica el ciclo de vida.
  // Aquí NO se hace POST ni PATCH: el lead sigue ATTEMPTING y el
  // Mantenimiento lo retiene mientras el registro esté sin resolver.
  // Sólo si el registro durable quedó CONFIRMADO; si no, se conserva
  // el comportamiento anterior (Activity inmediata): nunca se pierde
  // una llamada.
  // ------------------------------------------------------------
  if (
    String(j.outcome || '').toUpperCase() === 'CONNECTED' &&
    String(j.callStatus || '').toUpperCase() === 'ANSWERED' &&
    j.elevenlabs_call_id &&
    confirmedKeys.has('elevenlabs:' + j.elevenlabs_call_id)
  ) {
    deferred++;
    console.log(
      `⏳ Asterisk ${j.lead_id}: contestada → la Activity la crea WF9 ` +
      `al terminar (${j.elevenlabs_call_id})`
    );
    out.push({
      json: {
        ...j,
        deferred_to_wf9: true,
        patch_ok: null,
        patch_http: null,
        stage_requested: j.stage || null,
        stage_ok: null,
        stage_http: null,
        followup_ok: null,
        followup_id: null
      }
    });
    continue;
  }

  // ------------------------------------------------------------
  // FOLLOWUP
  // ------------------------------------------------------------
  let fu = null;

  if (j.logFollowup) {
    const fuBody = {
      type: 'CALL',
      outcome: j.outcome,
      callStatus: j.callStatus,
      durationSeconds: 0,
      notes: j.notes
    };

    if (j.nextFollowUpAt) {
      fuBody.nextActionAt =
        j.nextFollowUpAt;
    }

    fu = await api(
      'POST',
      `/leads/${j.lead_id}/followups`,
      {
        body: fuBody
      }
    );

    if (!fu.ok) {
      console.error(
        `⚠️ Followup falló ${j.lead_id} ` +
        `HTTP ${fu.status}`,
        JSON.stringify(
          fu.body
        ).slice(0, 200)
      );
    }
  }

  // ------------------------------------------------------------
  // STATUS
  // ------------------------------------------------------------
  let r = await api(
    'PATCH',
    `/leads/${j.lead_id}`,
    {
      body: {
        status: j.status
      }
    }
  );

  if (!r.ok) {
    r = await api(
      'PATCH',
      `/leads/${j.lead_id}`,
      {
        body: {
          status: j.status
        }
      }
    );
  }

  if (!r.ok) {
    fails++;

    console.error(
      `❌ PATCH status falló 2 veces ${j.lead_id} ` +
      `HTTP ${r.status}`,
      JSON.stringify(
        r.body
      ).slice(0, 200)
    );
  }

  // ------------------------------------------------------------
  // STAGE LOST
  // Solo cuando Classify lo solicita.
  // ------------------------------------------------------------
  let stageResult = null;

  if (
    r.ok &&
    j.stage
  ) {
    stageResult = await api(
      'PATCH',
      `/leads/${j.lead_id}`,
      {
        body: {
          stage: j.stage
        }
      }
    );

    if (!stageResult.ok) {
      // El status CLOSED ya quedó aplicado.
      // Por eso no existe riesgo de otra llamada.
      console.error(
        `⚠️ Stage ${j.stage} falló para ${j.lead_id} ` +
        `HTTP ${stageResult.status}. ` +
        `El status ${j.status} sí quedó aplicado.`
      );
    }
  }

  const followupId =
    fu &&
    fu.ok &&
    fu.body &&
    fu.body.followUp
      ? fu.body.followUp.id
      : null;

  out.push({
    json: {
      ...j,

      patch_ok: r.ok,
      patch_http: r.status,

      stage_requested:
        j.stage || null,

      stage_ok:
        stageResult
          ? stageResult.ok
          : null,

      stage_http:
        stageResult
          ? stageResult.status
          : null,

      followup_ok:
        fu
          ? fu.ok
          : null,

      followup_id:
        followupId
    }
  });
}

console.log(
  `🏁 Asterisk: ${out.length} guardados | ` +
  `${deferred} diferidos a WF9 | ` +
  `${fails} PATCH fallidos`
);

return out;

