async function listAll(status, dialCode) {
  const all = []; let offset = 0;
  for (let p = 0; p < MAX_PAGES; p++) {
    const r = await api('GET', '/leads', { qs: { status, dialCode, limit: 200, offset } });
    if (!r.ok) { console.error(`❌ GET /leads ${status} ${dialCode} HTTP ${r.status}`); break; }
    const leads = r.body.leads || [];
    all.push(...leads);
    offset += leads.length;
    if (leads.length < 200 || offset >= Number(r.body.total || 0)) break;
  }
  return all;
}
async function patchMany(list) {
  let ok = 0, fail = 0;
  for (let i = 0; i < list.length; i += 10) {
    const chunk = list.slice(i, i + 10);
    const res = await Promise.all(chunk.map(x => api('PATCH', `/leads/${x.id}`, { body: x.body })));
    res.forEach(r => r.ok ? ok++ : fail++);
  }
  return { ok, fail };
}

