  const stale = attempting.filter(l => l.status === 'ATTEMPTING' && l.updatedAt &&
    (now - new Date(l.updatedAt)) > STALE_MIN * 60000);
  const retryAt = new Date(now.getTime() + RETRY_HOURS * 3600000).toISOString();
  const staleOps = stale.map(l => ({ id: l.id, body: { status: 'NO_ANSWER', nextFollowUpAt: retryAt } }));
  const staleRes = await patchMany(staleOps);

  // 2) NO_ANSWER vencidos -> NOT_CONTACTED
  const noAnswer = await listAll('NO_ANSWER', c.dialCode);
  const due = noAnswer.filter(l => l.status === 'NO_ANSWER' && l.nextFollowUpAt && new Date(l.nextFollowUpAt) <= now);
  const dueRes = await patchMany(due.map(l => ({ id: l.id, body: { status: 'NOT_CONTACTED' } })));

  // 3) Salud
  const h = await api('GET', '/leads', { qs: { status: 'NOT_CONTACTED', dialCode: c.dialCode, limit: 1, offset: 0 } });
  const disponibles = h.ok ? Number(h.body.total || 0) : null;

  summary[c.key] = {
