// ============================================================================
// 📥 FETCH + LOCK (STRINGEE)
//
// Regla:
// 3 ciclos x 3 intentos = máximo 9.
//
// attempts 0-8  -> puede ir al worker.
// attempts >= 9 -> NO va al worker.
//                  status CLOSED.
//                  stage UNRESPONSIVE.
// ============================================================================

const MAX_ATTEMPTS = 9;

const COUNTRIES = [
  {
    key: 'india',
    dialCode: '91',
    prefix: '+91',
    batchSize: 5,

    lines: [
      '917971730907',
      '917944413269',
      '917944413268',
      '917971731010',
      '917943609115'
    ],

    fromEnd: true,
    minDigits: 10,
    maxDigits: 10,
    language: 'hi',

    agent_id:
      'agent_5701kramx550e3qs2tm11661b48p',

    agent_phone_number_id: ''
  }
];

const FETCH_MULT = 3;

function normalizePhone(raw, prefix) {
  let p = String(raw || '')
    .replace(/[^0-9+]/g, '');

  if (!p) return '';

  if (p.startsWith('+')) {
    return p;
  }

  const digits =
    prefix.replace('+', '');

  if (
    p.startsWith(digits) &&
    p.length > digits.length + 6
  ) {
    return '+' + p;
  }

  return prefix + p;
}

function safeAttempts(value) {
  const n = Number(value);

  if (!Number.isFinite(n) || n < 0) {
    return 0;
  }

  return Math.trunc(n);
}

async function closeExhaustedLead(
  leadId,
  attempts,
  country
) {
  // Primero cerrar.
  const close = await api(
    'PATCH',
    `/leads/${leadId}`,
    {
      body: {
        status: 'CLOSED'
      }
    }
  );

  if (!close.ok) {
    console.error(
      `🚨 Stringee ${country}: no se pudo cerrar ${leadId} ` +
      `con ${attempts} intentos. HTTP ${close.status}. ` +
      `Por seguridad NO se despacha.`
    );

    return {
      closed: false,
      lost: false
    };
  }

  // Después mover el stage a UNRESPONSIVE.
  const lost = await api(
    'PATCH',
    `/leads/${leadId}`,
    {
      body: {
        stage: 'UNRESPONSIVE'
      }
    }
  );

  if (!lost.ok) {
    console.error(
      `⚠️ Stringee ${country}: ${leadId} quedó CLOSED, ` +
      `pero stage UNRESPONSIVE falló HTTP ${lost.status}.`
    );
  }

  console.log(
    `⛔ Stringee ${country}: ${leadId} reached ` +
    `${attempts}/${MAX_ATTEMPTS} attempts → no dispatch`
  );

  return {
    closed: true,
    lost: lost.ok
  };
}

const out = [];

for (const c of COUNTRIES) {
  const limit = Math.min(
    200,
    c.batchSize * FETCH_MULT
  );

  let offset = 0;

  if (c.fromEnd) {
    const t = await api(
      'GET',
      '/leads',
      {
        qs: {
          status: 'NOT_CONTACTED',
          dialCode: c.dialCode,
          limit: 1,
          offset: 0
        }
      }
    );

    offset = t.ok
      ? Math.max(
          0,
          Number(t.body.total || 0) - limit
        )
      : 0;
  }

  const r = await api(
    'GET',
    '/leads',
    {
      qs: {
        status: 'NOT_CONTACTED',
        dialCode: c.dialCode,
        limit,
        offset
      }
    }
  );

  if (!r.ok) {
    console.error(
      `❌ Stringee ${c.key}: GET /leads falló HTTP ${r.status}`,
      JSON.stringify(r.body).slice(0, 300)
    );

    continue;
  }

  const leads = r.body.leads || [];

  const totalDisponibles =
    Number(r.body.total || 0);

  let taken = 0;
  let invalid = 0;
  let lockFail = 0;
  let exhausted = 0;

  for (const l of leads) {
    if (taken >= c.batchSize) break;

    if (!l || !l.id) continue;

    if (
      String(l.status || '').toUpperCase() !==
      'NOT_CONTACTED'
    ) {
      continue;
    }

    const currentAttempts =
      safeAttempts(l.attempts);

    // ==========================================================
    // HARD LIMIT
    // No permitir que un lead con 9+ attempts llegue al worker.
    // ==========================================================
    if (
      currentAttempts >=
      MAX_ATTEMPTS
    ) {
      await closeExhaustedLead(
        l.id,
        currentAttempts,
        c.key
      );

      exhausted++;
      continue;
    }

    if (l.doNotCall) {
      await api(
        'PATCH',
        `/leads/${l.id}`,
        {
          body: {
            status: 'CLOSED'
          }
        }
      );

      invalid++;
      continue;
    }

    const phone =
      normalizePhone(
        l.phone,
        c.prefix
      );

    const national =
      phone.slice(
        c.prefix.length
      );

    const validPhone =
      /^\+[1-9]\d{7,14}$/.test(phone) &&
      phone.startsWith(c.prefix) &&
      national.length >= c.minDigits &&
      national.length <= c.maxDigits;

    if (!validPhone) {
      await api(
        'PATCH',
        `/leads/${l.id}`,
        {
          body: {
            status: 'UNREACHABLE'
          }
        }
      );

      console.log(
        `🚫 ${c.key}: teléfono inválido '${l.phone}' ` +
        `→ UNREACHABLE (${l.id})`
      );

      invalid++;
      continue;
    }

    // Lock antes de llamar.
    const lock = await api(
      'PATCH',
      `/leads/${l.id}`,
      {
        body: {
          status: 'ATTEMPTING'
        }
      }
    );

    if (!lock.ok) {
      lockFail++;

      console.error(
        `🔒❌ ${c.key}: no se pudo bloquear ` +
        `${l.id} HTTP ${lock.status}`
      );

      continue;
    }

    out.push({
      json: {
        provider: 'stringee',

        lead_id: l.id,

        full_name:
          String(l.name || '').trim() ||
          'User',

        phone,

        country: c.key,

        language:
          String(
            l.language ||
            c.language
          )
            .trim()
            .toLowerCase(),

        call_attempts:
          currentAttempts,

        _agent_id:
          c.agent_id,

        _agent_phone_number_id:
          c.agent_phone_number_id,

        _from_number:
          c.lines
            ? c.lines[
                taken %
                c.lines.length
              ]
            : (
                c.from_number ||
                ''
              )
      }
    });

    taken++;
  }

  const msg =
    `📥 Stringee ${c.key}: ` +
    `${totalDisponibles} NOT_CONTACTED | ` +
    `${leads.length} leídos | ` +
    `${taken} bloqueados | ` +
    `${exhausted} agotaron ${MAX_ATTEMPTS} intentos | ` +
    `${invalid} inválidos | ` +
    `${lockFail} lock fallidos`;

  if (
    taken === 0 &&
    totalDisponibles > 0
  ) {
    console.error(
      '🚨 Hay leads disponibles pero 0 llegaron al batch — ' +
      msg
    );
  } else {
    console.log(msg);
  }
}

return out;

