// ============================================================================
// 🧹 MANTENIMIENTO (cada 5 min) — red de seguridad para que NUNCA quede un lead
// muerto, SIN romper el límite de 9 intentos. Hace su propio login y usa
// GET /leads con paginación real.
//  0. Lee de MySQL (nodo anterior) qué leads tienen un job Stringee SIN resolver
//     y qué reintentos retuvo WF9 (next_retry_at). Si esa consulta falló, NO se
//     libera ni se reactiva nada (fail-safe) y se avisa con 🚨.
//  1. ATTEMPTING colgado > STALE_MIN:
//       - con job Stringee sin resolver  -> NO se toca (WF9 lo va a cerrar)
//       - attempts >= 9                  -> CLOSED + stage UNRESPONSIVE
//       - resto                          -> NO_ANSWER (no suma intento)
//  2. NO_ANSWER:
//       - attempts >= 9 -> CLOSED + stage UNRESPONSIVE (nunca vuelve a la cola)
//       - vencido       -> NOT_CONTACTED (vuelve a la cola)
//     "Vencido" usa, en este orden: el reintento retenido por WF9 (next_retry_at),
//     lead.nextFollowUpAt si fue fijado después del último cambio del lead, o
//     (si falta / quedó viejo) la última actualización + el ciclo 3x3 según attempts.
//     (LeadStudio ignora PATCH nextFollowUpAt — sólo lo fija nextActionAt del
//     POST /followups — por eso este nodo ya no lo intenta escribir.)
//  3. Reporta cuántos NOT_CONTACTED hay por país (salud)
// Primero se juntan TODOS los IDs y recién después se hacen los PATCH, para que
// la paginación por offset no se corra al ir cambiando estados.
// ============================================================================
const BASE = 'https://lead-studio-9gnl.onrender.com/api';
const DIAL_CODES = [{ key: 'india', dialCode: '91' }, { key: 'nepal', dialCode: '977' }];
const STALE_MIN = 30;
const MAX_ATTEMPTS = 9;
const EXHAUSTED_STAGE = 'UNRESPONSIVE';
const MAX_PAGES = 25;     // hasta 5.000 leads por status/país por corrida
const self = this;
let TOKEN = '';

async function api(method, path, opts = {}) {
  try {
    const r = await self.helpers.httpRequest({
      method, url: BASE + path, qs: opts.qs, body: opts.body, json: true,
      headers: Object.assign({ 'Content-Type': 'application/json' }, TOKEN ? { Authorization: 'Bearer ' + TOKEN } : {}),
      returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 20000
    });
    return { ok: r.statusCode >= 200 && r.statusCode < 300, status: r.statusCode, body: r.body || {} };
  } catch (e) { return { ok: false, status: 0, body: { error: String(e.message || e) } }; }
}

// ---------- 0) Estado de eventos (MySQL) ----------
const dbRows = $input.all().map(i => i.json || {});
const dbOk = dbRows.some(r => r.kind === 'ok') && !dbRows.some(r => r.error || r.message && !r.kind);
const unresolved = new Map();   // lead_id -> { n, sinceMs }
const holds = new Map();        // lead_id -> { holdMs, setMs }
let stuckFailed = 0;
for (const r of dbRows) {
  if (r.kind === 'unresolved' && r.lead_id) unresolved.set(String(r.lead_id), { n: Number(r.n) || 0, sinceMs: Number(r.set_ms) || 0 });
  if (r.kind === 'hold' && r.lead_id && Number(r.hold_ms) > 0) {
    const prev = holds.get(String(r.lead_id));
    if (!prev || Number(r.hold_ms) > prev.holdMs) holds.set(String(r.lead_id), { holdMs: Number(r.hold_ms), setMs: Number(r.set_ms) || 0 });
  }
  if (r.kind === 'stuck') stuckFailed = Number(r.n) || 0;
}
if (!dbOk) {
  console.error('🚨 Mantenimiento: la consulta a wf_call_events falló. Fail-safe: no se libera ni se reactiva ningún lead en esta corrida.', JSON.stringify(dbRows).slice(0, 300));
}
if (stuckFailed > 0) console.error(`🚨 wf_call_events: ${stuckFailed} eventos FAILED con 5+ errores — revisar WF9`);

const login = await api('POST', '/auth/login', { body: { email: 'ai@leadstudio.com', password: 'Admin@123' } });
if (!login.ok || !login.body.accessToken) {
  console.error('❌ Mantenimiento: login falló', login.status, JSON.stringify(login.body).slice(0, 200));
  return [{ json: { error: true, step: 'login', status: login.status } }];
}
TOKEN = login.body.accessToken;

async function listAll(status, dialCode) {
  const all = []; let offset = 0;
  for (let p = 0; p < MAX_PAGES; p++) {
    const r = await api('GET', '/leads', { qs: { status, dialCode, limit: 200, offset } });
    if (!r.ok) { console.error(`❌ GET /leads ${status} ${dialCode} HTTP ${r.status}`); break; }
    const leads = r.body.leads || [];
    all.push(...leads);
    offset += leads.length;
    if (leads.length < 200 || offset >= Number(r.body.total || 0)) break;
  }
  return all;
}
// Cada op es una lista de PATCH secuenciales para el mismo lead (status primero, stage después)
async function patchMany(list) {
  let ok = 0, fail = 0;
  for (let i = 0; i < list.length; i += 10) {
    const chunk = list.slice(i, i + 10);
    const res = await Promise.all(chunk.map(async x => {
      for (const body of x.bodies) {
        let r = await api('PATCH', `/leads/${x.id}`, { body });
        if (!r.ok && r.status === 400 && 'nextFollowUpAt' in body) {
          // si el backend no acepta nextFollowUpAt=null, el cierre se aplica igual sin ese campo
          const b2 = Object.assign({}, body); delete b2.nextFollowUpAt;
          r = await api('PATCH', `/leads/${x.id}`, { body: b2 });
        }
        if (!r.ok) { console.error(`⚠️ PATCH ${x.id} ${JSON.stringify(body)} HTTP ${r.status}`); return false; }
      }
      return true;
    }));
    res.forEach(r => r ? ok++ : fail++);
  }
  return { ok, fail };
}
function safeAttempts(v) { const n = Number(v); return Number.isFinite(n) && n >= 0 ? Math.trunc(n) : 0; }
function msOf(v) { const t = v ? new Date(v).getTime() : NaN; return Number.isFinite(t) ? t : null; }
function addBusinessDays(d, days) {
  const r = new Date(d.getTime()); let added = 0;
  while (added < days) { r.setDate(r.getDate() + 1); const wd = r.getDay(); if (wd !== 0 && wd !== 6) added++; }
  return r;
}
// Próximo intento según el ciclo 3x3 (mismo cálculo que WF2 / WF9)
function policyDue(attempts, baseMs) {
  const a = Math.max(1, attempts);
  const pos = ((a - 1) % 3) + 1;
  const cycle = Math.ceil(a / 3);
  const base = new Date(baseMs);
  if (pos === 1) return baseMs + 2 * 3600000;
  if (pos === 2) return baseMs + 3 * 3600000;
  return addBusinessDays(base, cycle === 1 ? 2 : 3).getTime();
}
const closeOp = id => ({ id, bodies: [{ status: 'CLOSED', nextFollowUpAt: null }, { stage: EXHAUSTED_STAGE }] });

const now = new Date();
const nowMs = now.getTime();
const summary = {};
for (const c of DIAL_CODES) {
  // 1) ATTEMPTING colgados
  const attempting = await listAll('ATTEMPTING', c.dialCode);
  const stale = attempting.filter(l => l.status === 'ATTEMPTING' && l.updatedAt &&
    (nowMs - new Date(l.updatedAt).getTime()) > STALE_MIN * 60000);
  const staleOps = [];
  let heldByJob = 0, closedAttempting = 0;
  if (dbOk) {
    for (const l of stale) {
      const u = unresolved.get(String(l.id));
      if (u && u.n > 0) {
        heldByJob++;
        if (u.sinceMs && nowMs - u.sinceMs > 2 * 3600000) console.error(`🚨 ${c.key}: ${l.id} lleva >2 h en ATTEMPTING con job Stringee sin resolver`);
        continue;
      }
      if (safeAttempts(l.attempts) >= MAX_ATTEMPTS) { staleOps.push(closeOp(l.id)); closedAttempting++; continue; }
      staleOps.push({ id: l.id, bodies: [{ status: 'NO_ANSWER' }] });
    }
  }
  const staleRes = await patchMany(staleOps);

  // 2) NO_ANSWER: agotados -> CLOSED/UNRESPONSIVE ; vencidos -> NOT_CONTACTED
  const noAnswer = await listAll('NO_ANSWER', c.dialCode);
  const exhaustedOps = [];
  const dueOps = [];
  let heldByRetry = 0, recomputed = 0;
  for (const l of noAnswer) {
    if (l.status !== 'NO_ANSWER') continue;
    const attempts = safeAttempts(l.attempts);
    if (attempts >= MAX_ATTEMPTS) { exhaustedOps.push(closeOp(l.id)); continue; }
    if (!dbOk) continue; // sin datos de reintentos retenidos no se reactiva nada
    if (l.doNotCall) continue;
    const upd = msOf(l.updatedAt) || nowMs;
    const h = holds.get(String(l.id));
    let dueMs;
    if (h && h.holdMs && (!h.setMs || upd <= h.setMs + 120000)) {
      dueMs = h.holdMs;                        // reintento retenido por WF9 (corrección de buzón)
      if (dueMs > nowMs) heldByRetry++;
    } else {
      const nf = msOf(l.nextFollowUpAt);
      if (nf && nf >= upd - 10 * 60000) {
        dueMs = nf;                            // fijado por nextActionAt en la última llamada
      } else {
        dueMs = policyDue(attempts, upd);      // faltante o viejo: se recalcula (no se reactiva en falso)
        recomputed++;
      }
    }
    if (dueMs <= nowMs) dueOps.push({ id: l.id, bodies: [{ status: 'NOT_CONTACTED' }] });
  }
  const exhaustedRes = await patchMany(exhaustedOps);
  const dueRes = await patchMany(dueOps);

  // 3) Salud
  const h = await api('GET', '/leads', { qs: { status: 'NOT_CONTACTED', dialCode: c.dialCode, limit: 1, offset: 0 } });
  const disponibles = h.ok ? Number(h.body.total || 0) : null;

  summary[c.key] = {
    attempting_total: attempting.length,
    attempting_colgados: stale.length,
    attempting_retenidos_por_job: heldByJob,
    attempting_liberados: staleRes.ok,
    attempting_cerrados_agotados: closedAttempting,
    no_answer_total: noAnswer.length,
    no_answer_cerrados_agotados: exhaustedRes.ok,
    no_answer_reactivados: dueRes.ok,
    no_answer_retenidos_wf9: heldByRetry,
    no_answer_vencimiento_recalculado: recomputed,
    patch_fallidos: staleRes.fail + exhaustedRes.fail + dueRes.fail,
    not_contacted_disponibles: disponibles,
    db_ok: dbOk
  };
  console.log(`🧹 ${c.key}:`, JSON.stringify(summary[c.key]));
  if (disponibles === 0) console.error(`🚨 ${c.key}: 0 leads NOT_CONTACTED — el dialer no tiene a quién llamar`);
}
return [{ json: { ran_at: now.toISOString(), ...summary } }];

// ============================================================================
// 🧾 BUILD DEFERRED LEDGER (ASTERISK) — llamada Asterisk CONTESTADA.
//
// Por qué existe: LeadStudio fija durationSeconds en el POST /followups y NO lo deja
// editar después (PATCH /followups/{id} -> 400 "Nothing to update"). Este nodo corre
// cuando la llamada acaba de ser contestada (la API de ElevenLabs responde al contestar,
// no al colgar), o sea antes de conocer el billsec real. Por eso la Activity de una
// llamada contestada la crea WF9 al TERMINAR la llamada (con CDR.billsec).
//
// Aquí sólo se deja un registro durable en wf_call_events con la MISMA clave que usan el
// webhook y el polling de ElevenLabs (elevenlabs:<conversation_id>): mismo evento, sin
// duplicados. dispatched_at es la marca "esta llamada la creará WF9".
// Luego se CONFIRMA con un SELECT: 🏁 Guardar Resultado (Asterisk) sólo difiere la Activity
// de las llamadas confirmadas; si el registro falla, crea la Activity como antes (nunca se
// pierde una llamada).
// Sin llamadas contestadas en este lote -> consulta vacía (SELECT 1).
// Horas en UTC explícito.
// ============================================================================
const CONV_RE = /^conv_[A-Za-z0-9]{8,64}$/;
function q(v) {
  if (v === null || v === undefined || v === '') return 'NULL';
  if (typeof v === 'number') return Number.isFinite(v) ? String(Math.trunc(v)) : 'NULL';
  return "'" + String(v).replace(/\u0000/g, '').replace(/[\r\n]+/g, ' ').replace(/\$/g, '').replace(/\\/g, '\\\\').replace(/'/g, "''")
    .replace(/\{\{/g, '{ {').replace(/\}\}/g, '} }') + "'";
}
function dt(v) {
  const t = v ? new Date(v).getTime() : NaN;
  return Number.isFinite(t) ? "'" + new Date(t).toISOString().replace('T', ' ').replace('Z', '') + "'" : 'UTC_TIMESTAMP(3)';
}
const locked = $('📥 Fetch + Lock (Asterisk)1').all().map(i => i.json || {});
const phoneOf = id => { const l = locked.find(x => x.lead_id === id); return l ? String(l.phone || '').replace(/[^0-9+]/g, '').slice(0, 32) : null; };
const rows = [];
const keys = [];
for (const it of $input.all()) {
  const j = it.json || {};
  if (String(j.outcome || '').toUpperCase() !== 'CONNECTED' || String(j.callStatus || '').toUpperCase() !== 'ANSWERED') continue;
  const conv = String(j.elevenlabs_call_id || '');
  if (!CONV_RE.test(conv) || !j.lead_id) continue;
  const att = Number(j.attempts);
  const key = 'elevenlabs:' + conv;
  if (keys.includes(q(key))) continue;
  keys.push(q(key));
  rows.push('(' + [q(key), q('elevenlabs'), q('asterisk'), q(conv), q(String(j.lead_id).slice(0, 64)), q(phoneOf(j.lead_id)),
    q(Number.isInteger(att) && att >= 1 && att <= 99 ? att : null), dt(j.last_call_time), dt(j.last_call_time), 'UTC_TIMESTAMP(3)', q('RECEIVED'),
    'UTC_TIMESTAMP(3) + INTERVAL 3 MINUTE', q(JSON.stringify({ via: 'wf2_asterisk_answered_deferred' }))].join(', ') + ')');
}
if (!rows.length) return [{ json: { ledger_rows: 0, ledger_sql: 'SELECT 1 AS noop' } }];
const ledger_sql = 'INSERT INTO wf_call_events (event_key, source, provider, external_id, lead_id, phone, call_attempts, ' +
  'event_at, dispatched_at, first_seen_at, state, next_attempt_at, payload) VALUES ' + rows.join(', ') +
  ' ON DUPLICATE KEY UPDATE provider = VALUES(provider), lead_id = COALESCE(lead_id, VALUES(lead_id)), ' +
  'phone = COALESCE(phone, VALUES(phone)), call_attempts = COALESCE(call_attempts, VALUES(call_attempts)), ' +
  'event_at = COALESCE(event_at, VALUES(event_at)), dispatched_at = COALESCE(dispatched_at, VALUES(dispatched_at))' +
  '; SELECT event_key FROM wf_call_events WHERE dispatched_at IS NOT NULL AND event_key IN (' + keys.join(', ') + ')';
console.log(`🧾 Asterisk contestadas: ${rows.length} llamada(s) registradas para que WF9 cree la Activity al terminar`);
return [{ json: { ledger_rows: rows.length, ledger_sql } }];
